"use strict";(self.webpackChunkmonogame_extended_website=self.webpackChunkmonogame_extended_website||[]).push([[4207],{8812:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>c,frontMatter:()=>a,metadata:()=>s,toc:()=>l});var o=n(4848),i=n(8453);const a={slug:"ai-contributions-and-the-future-of-monogame-extended",title:"AI Contributions and the Future of MonoGame.Extended.",authors:"aris",tags:["ai","contributions"],enableComments:!0},r=void 0,s={permalink:"/blog/ai-contributions-and-the-future-of-monogame-extended",editUrl:"https://github.com/monogame-extended/monogame-extended.github.io/tree/develop/blog/2026-08-10/ai-contributions.md",source:"@site/blog/2026-08-10/ai-contributions.md",title:"AI Contributions and the Future of MonoGame.Extended.",description:"Hi everyone,",date:"2026-08-10T00:00:00.000Z",tags:[{inline:!0,label:"ai",permalink:"/blog/tags/ai"},{inline:!0,label:"contributions",permalink:"/blog/tags/contributions"}],readingTime:10.32,hasTruncateMarker:!1,authors:[{name:"Christopher Whitley (AristurtleDev)",title:"MonoGame.Extended Maintainer",url:"https://github.com/aristurtledev",imageURL:"https://github.com/aristurtledev.png",key:"aris"}],frontMatter:{slug:"ai-contributions-and-the-future-of-monogame-extended",title:"AI Contributions and the Future of MonoGame.Extended.",authors:"aris",tags:["ai","contributions"],enableComments:!0},unlisted:!1,nextItem:{title:"Version 6.0.0 - 2D Geometry, Tilemaps, Collision, and ECS Updates",permalink:"/blog/version-6"}},h={authorsImageUrls:[void 0]},l=[{value:"MonoGame.Extended as a Learning Resource",id:"monogameextended-as-a-learning-resource",level:2},{value:"Open Source Is More Than Just Code",id:"open-source-is-more-than-just-code",level:2},{value:"Other Projects Are Asking The Same Questions",id:"other-projects-are-asking-the-same-questions",level:2},{value:"Where AI Generated Contributions Become a Problem",id:"where-ai-generated-contributions-become-a-problem",level:2},{value:"What About Using AI as a Tool?",id:"what-about-using-ai-as-a-tool",level:2},{value:"Staying Aligned With MonoGame",id:"staying-aligned-with-monogame",level:2},{value:"A New Contribution Policy",id:"a-new-contribution-policy",level:2},{value:"Looking Ahead",id:"looking-ahead",level:2}];function d(e){const t={a:"a",blockquote:"blockquote",h2:"h2",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"Hi everyone,"}),"\n",(0,o.jsx)(t.p,{children:"I wanted to take some time to talk about something a little different from the usual development and release updates. Specifically I wanted to hit on the topic everyone wants no one to talk about, and that's AI generated code contributions, the role that opens source projects play in helping developers learn, and why MonoGame.Extended will not be accepting AI generated contributions."}),"\n",(0,o.jsx)(t.p,{children:"This is something I've given quite a bit of though about. While I have my own options about the increasing use of AI in software development, this decision is not simply about that. It's not about whether AI can produce working code. It's more about what I believe MonoGame.Extended should be as an open source project, and what I want to encourage within the community."}),"\n",(0,o.jsx)(t.h2,{id:"monogameextended-as-a-learning-resource",children:"MonoGame.Extended as a Learning Resource"}),"\n",(0,o.jsx)(t.p,{children:"MonoGame.Extended is a library developers get introduced to fairly early on when they first start working with MonoGame. It provides a collection of common tools and systems that help developers get started without having to implement everything themselves."}),"\n",(0,o.jsx)(t.p,{children:"Things like cameras, animations, screen management, collision detection, and entity component systems are all things that developers will likely encounter as they begin building more complex games."}),"\n",(0,o.jsx)(t.p,{children:"MonoGame.Extended was a huge learning resource for me when I first started getting into MonoGame itself and without it, I don't know if I would have been able to catch on to MonoGame development as quickly as I did."}),"\n",(0,o.jsx)(t.p,{children:"It's more than just a collection of reusable code. It's also a place where developers can look through the source and see how those systems are implemented. Someone who has never written a camera system before can look at how ours works. Someone interested in particle systems can explore the implementation, understand the decisions that were made, and potentially take that knowledge into their own projects."}),"\n",(0,o.jsx)(t.p,{children:"In that sense, MonoGame.Extended serves as both a library and a learning resource."}),"\n",(0,o.jsx)(t.p,{children:"And i think there's an important part to that. As developers become more familiar with MonoGame and MonoGame.Extended, I hope they eventually feel comfortable enough to contribute back to the project themselves. Maybe that's just fixing a bug they encountered or implementing something new they feel would benefit others.  And hopefully this can serve as a stepping stone for those developers to go on to contribute to MonoGame itself as well."}),"\n",(0,o.jsx)(t.h2,{id:"open-source-is-more-than-just-code",children:"Open Source Is More Than Just Code"}),"\n",(0,o.jsx)(t.p,{children:"One of the things I think gets overlooked when discussing open source contributions is that the value of a contribution isn't necessarily limited to the code that gets merged. There's also value in the process of making that contribution."}),"\n",(0,o.jsx)(t.p,{children:"A developer might come into the project with an idea for a feature, but not be entirely sure how to implement it. They spend some time looking through existing code, figuring out how things work, and putting together an initial implementation. Maybe that implementation has some problems, maybe there are edge cases they didn't consider, or there may be a better approach they were not aware of. Through the review process, they get feedback, learn why certain decisions are made, and hopefully walk away with a better understanding of the codebase and software development in general."}),"\n",(0,o.jsx)(t.p,{children:"And that's a good thing."}),"\n",(0,o.jsx)(t.p,{children:"I don't expect every contributor to be an expert, and I certainly don't expect every pull request to be perfect when it's first submitted. Part of contributing to open source projects is learning how to work within an existing codebase and learning from the people who have experience maintaining it."}),"\n",(0,o.jsx)(t.p,{children:"Over time, those contributors become more familiar with the project. They begin to understand not just how the code works, but why it works that way. Eventually they may become the people reviewing contributions and helping newer developers themselves. The cycle of learning, contributing, and eventually helping others is something I consider an important part of open source development."}),"\n",(0,o.jsx)(t.h2,{id:"other-projects-are-asking-the-same-questions",children:"Other Projects Are Asking The Same Questions"}),"\n",(0,o.jsx)(t.p,{children:"Monogame.Extended is not the only open source project considering how AI generated contributions affect the development and review process."}),"\n",(0,o.jsxs)(t.p,{children:[(0,o.jsx)(t.a,{href:"https://www.youtube.com/watch?v=iqddnwKF8HQ",children:"Recently, Andrew Kelley, the creator of the Zig programming language, discussed why Zig doesn't accept AI generated contributions during an interview with JetBrains"}),".  One of the points he made that particularly resonated with me was that reviewing contributions isn't just about improving the code being submitted. It's also an opportunity to mentor developers and help them grow into more experienced contributors."]}),"\n",(0,o.jsx)(t.p,{children:"He describes this as contributor poker, where maintainers have a limited amount of time to invest in reviewing contributions, and part of that investment is helping developers become more capable of contributing to the project in the future."}),"\n",(0,o.jsx)(t.p,{children:"Kelley also explains that Zig considers education part of its mission, stating:"}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:'"The Zig project is also an education project. That\'s part of our mission statement."'}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"I think this applies particularly well to MonoGame.Extended, and I'm happy to make time for that investment for contributors.  But when the implementation and subsequent review feedback are being handed off to an AI agent, much of that educational opportunity is lost."}),"\n",(0,o.jsxs)(t.p,{children:["The Linux kernel community has also been discussing how AI generated contributions should be handled. ",(0,o.jsx)(t.a,{href:"https://cdn.kernel.org/doc/html/latest/process/generated-content.html",children:"Their approach isn't quite the same as Zig's, they do not prohibit AI contributions outright"}),", but there is a point in their guidelines that i think is important"]}),"\n",(0,o.jsxs)(t.blockquote,{children:["\n",(0,o.jsx)(t.p,{children:'"You are expected to understand and be able to defend everything you submit."'}),"\n"]}),"\n",(0,o.jsx)(t.p,{children:"That might seem like an obvious expectation, but it's worth emphasizing. When someone contributes code to an open source project, they are taking responsibility for that contribution. That means being able to explain how it works, why decisions were made, and how to address problems discovered during review."}),"\n",(0,o.jsx)(t.p,{children:"While different projects may draw different lines in the sand, the underlying concern is the same. The responsibility for the contribution needs to remain with the person submitting it, and the review process needs to be a meaningful interaction between developers."}),"\n",(0,o.jsx)(t.h2,{id:"where-ai-generated-contributions-become-a-problem",children:"Where AI Generated Contributions Become a Problem"}),"\n",(0,o.jsx)(t.p,{children:"This brings me to the issue with AI generated contributions. With the tools available today, it's becoming increasingly easy for someone to describe a feature or bug to an agent, have it generate an implementation, and submit the resulting changes."}),"\n",(0,o.jsx)(t.p,{children:"And to be clear, the code that comes out of that process might work. It might even be a perfectly reasonable implementation of the requested feature. But whether the code works isn't the only thing I'm concerned about."}),"\n",(0,o.jsx)(t.p,{children:"When someone submits a contribution, they should be understand what they are submitting, the decisions they made, and why they approached the problem the way they did and how it fits into the existing codebase. When the process is handed off to an AI agent, much of the opportunity for learning gets lost."}),"\n",(0,o.jsx)(t.p,{children:"There's also the matter of reviewing these contributions. Reviewing a pull requests takes time, especially when the changes involve systems that have to remain compatible with existing functionality or follow design patterns.  When I provide feedback on a contribution, I'm not just trying to get the code into a state where it can be merged, I'm also trying to help the contributor understand why I'm requesting those changes."}),"\n",(0,o.jsx)(t.p,{children:"If that feedback is simply passed back to an agent to generate another implementation, the review process just becomes an exchange between a maintainer and an agent, which leaves the contributor as an intermediary.  That's not the kind of contribution process I want to encourage with MonoGame.Extended."}),"\n",(0,o.jsx)(t.p,{children:"I'd much rather spend time helping someone work through an implementation that they wrote than spend the same time reviewing an implementation generated by an agent.  The first has potential to help develop someone who will continue contributing to the project and the broader MonoGame ecosystem."}),"\n",(0,o.jsx)(t.h2,{id:"what-about-using-ai-as-a-tool",children:"What About Using AI as a Tool?"}),"\n",(0,o.jsx)(t.p,{children:"I do want to make this distinction here, because I recognize that AI is being used in a lot of different way by developers. There's a difference between using AI to help understand something and having AI generate the implementation for you."}),"\n",(0,o.jsx)(t.p,{children:"For example, someone might use AI to help explain an unfamiliar API, understand a compiler error, or learn about a programming concept they haven't encountered before. Those are uses where AI can potentially support the learning process rather than replace it. My concern is with contributions where an agent is response for producing the implementation that is being submitted to the project."}),"\n",(0,o.jsx)(t.p,{children:"I'm not interested in trying to dictate what tools people can or cannot use when working on their own projects, that's up to them. But when it comes to contributing code to MonoGame.Extended, I want those contributions to represent the work an understanding of the developers submitting them."}),"\n",(0,o.jsx)(t.h2,{id:"staying-aligned-with-monogame",children:"Staying Aligned With MonoGame"}),"\n",(0,o.jsx)(t.p,{children:"There's also something else worth mentioning here, and that is MonoGame itself."}),"\n",(0,o.jsx)(t.p,{children:"Monogame already has an established policy against AI generated contributions. Its contribution guidelines explicitly prohibit submitting code, documentation, bug fixes, or other content generated by LLMS or generative AI tools."}),"\n",(0,o.jsx)(t.p,{children:"As a library build on top of MonoGame, I think it's important that Monogame.Extended follows a similar philosophy when it comes to contributions.  On of the things I hope to encourage through Monogame.Extended is for developers to become more comfortable working with the MonoGame framework itself."}),"\n",(0,o.jsx)(t.p,{children:"I don't want there to be a disconnect between the contribution expectation of MonoGame.Extended and Monogame, especially when part of what I want to encourage is that progression from using the libraries to helping maintain them."}),"\n",(0,o.jsx)(t.p,{children:"So while this decision is ultimately about MonoGame.Extended, it is also consistent with the direction MonoGame has already taken."}),"\n",(0,o.jsx)(t.h2,{id:"a-new-contribution-policy",children:"A New Contribution Policy"}),"\n",(0,o.jsx)(t.p,{children:"With all of this in mind, Monogame.Extended will no longer accept pull requests containing AI generated implementations.  Contributors are expected to write and understand the code they submit and be able to participate directly in the review process. AI can still be used as a learning or reference tool, but it should not be used to generate the code being contributed."}),"\n",(0,o.jsx)(t.p,{children:"I also want to establish clearer expectations around transparency. If AI tools were using during the development of a contribution, that involvement should be disclosed in the pull request description.  The existing contribution guidelines already establish the expectation that contributors should personally write the code they submit. However, they have not explicitly addressed how that expectation applies to AI generated code.  This is something I'll be updating to make sure the expectations are clear for everyone going forward."}),"\n",(0,o.jsx)(t.p,{children:"I recognize there will be differing opinions on this decision, particularly as AI tools continue to become more common in software development. Some developers may feel that the only thing that should matter is whether the submitted code is correct and meets the project's requirements. I understand that perspective, but I don't agree that the resulting code is the only thing that matters for this project."}),"\n",(0,o.jsx)(t.p,{children:"And I want to emphasize this is not about questioning anyone's ability as a developer or suggesting that using AI somehow makes someone less capable. It's about the kind of contribution process I want to encourage and the role I believe Monogame.Extended should play in helping developers learn."}),"\n",(0,o.jsx)(t.h2,{id:"looking-ahead",children:"Looking Ahead"}),"\n",(0,o.jsx)(t.p,{children:"MonoGame.Extended has benefited from the work of many contributors over the years, and I want that to continue. I want developers to feel comfortable opening issues, asking questions, discussing implementations, and submitting pull requests even if they're not entirely confident that their first attempt is the best solution."}),"\n",(0,o.jsx)(t.p,{children:"You don't need to know everything about the library before contributing.  You don't need to have years of experience working with C# or MonoGame. And you certainly don't need to have a perfect implementation ready before starting a discussion.  What matters to me is that you are will to put in the effort to learn, understand the code you are working with, and participate in the process."}),"\n",(0,o.jsx)(t.p,{children:"I would rather help someone learn how to implement something than simply accept an implementation that had an agent produce it for them."}),"\n",(0,o.jsx)(t.p,{children:"Ultimately, I want MonoGame.Extended to continue being a place where developers can not only find useful tools for building their games, but also learn from code, improve their skills, and eventually contribute back to the MonoGame community as a whole."}),"\n",(0,o.jsx)(t.p,{children:"As always, if you have questions or concerns about this decision, feel free to reach out."}),"\n",(0,o.jsx)(t.p,{children:"Thank you all for your continued contributions and support."}),"\n",(0,o.jsx)(t.p,{children:"- \u2764 Chris Whitley (AristurtleDev)"})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>s});var o=n(6540);const i={},a=o.createContext(i);function r(e){const t=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);